import React, { useState } from 'react';
import { Search, MapPin, Briefcase, ChevronLeft } from 'lucide-react';
import { Link } from 'react-router-dom';

const SearchOffers = () => {
  const [ setSearchTerm] = useState("");
  // بيانات تجريبية لمحاكاة الواقع
  const offers = [
    { id: 1, title: "مطور ويب React", company: "Tech Solutions", location: "قسنطينة", type: "PFE" },
    { id: 2, title: "مصمم UI/UX", company: "Creative Agency", location: "الجزائر", type: "Classic" },
  ];

  return (
    <div className="p-6 max-w-6xl mx-auto" dir="rtl">
      <h1 className="text-2xl font-bold mb-6">استكشاف العروض المتاحة</h1>
      
      {/* شريط البحث والفلاتر */}
      <div className="flex flex-col md:flex-row gap-4 mb-8">
        <div className="relative flex-1">
          <Search className="absolute right-3 top-3 text-slate-400" size={20} />
          <input 
            type="text" 
            placeholder="ابحث عن تقنية (React, Django...)" 
            className="w-full pr-10 p-3 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-600"
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <select className="p-3 bg-white border border-slate-200 rounded-xl outline-none">
          <option>كل الولايات</option>
          <option>قسنطينة</option>
          <option>الجزائر</option>
        </select>
      </div>

      {/* قائمة العروض */}
      <div className="grid gap-4">
        {offers.map(offer => (
          <Link key={offer.id} to={`/student/internship/${offer.id}`} className="bg-white p-5 rounded-2xl border border-slate-100 hover:shadow-md transition-all flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-blue-50 rounded-xl flex items-center justify-center text-blue-600">
                <Briefcase size={24} />
              </div>
              <div>
                <h3 className="font-bold text-lg">{offer.title}</h3>
                <div className="flex gap-4 text-sm text-slate-500 mt-1">
                  <span className="flex items-center gap-1"><MapPin size={14} /> {offer.location}</span>
                  <span className="font-medium text-blue-600">{offer.type}</span>
                </div>
              </div>
            </div>
            <ChevronLeft className="text-slate-300" />
          </Link>
        ))}
      </div>
    </div>
  );
};

export default SearchOffers;
